DROP TABLE IF EXISTS `pedido`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pedido` (
  `num_pedido` varchar(20) NOT NULL,
  `incotern` enum('EXW','FCA','CPT','CIP','DAP','DPU','DDP','FAS','FOB','CFR','CIF') NOT NULL,
  `pedidocol` varchar(50) DEFAULT NULL,
  `edificio_id_sale` bigint NOT NULL,
  `edificio_id_llega` bigint NOT NULL,
  `cliente_id` bigint NOT NULL,
  `proveedor_id` bigint unsigned NOT NULL,
  PRIMARY KEY (`num_pedido`),
  KEY `fk_pedido_edificio1_idx` (`edificio_id_sale`),
  KEY `fk_pedido_edificio2_idx` (`edificio_id_llega`),
  KEY `fk_pedido_cliente1_idx` (`cliente_id`),
  KEY `fk_pedido_proveedor1_idx` (`proveedor_id`),
  CONSTRAINT `fk_pedido_cliente1` FOREIGN KEY (`cliente_id`) REFERENCES `cliente` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_edificio1` FOREIGN KEY (`edificio_id_sale`) REFERENCES `edificio` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_edificio2` FOREIGN KEY (`edificio_id_llega`) REFERENCES `edificio` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_pedido_proveedor1` FOREIGN KEY (`proveedor_id`) REFERENCES `proveedor` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
